workflows.on:
push:
    paths: ["ota/publish-request.json"]
  workflow_dispatch:
    inputs:
      channel: { description: "dev or stable", required: true, default: "dev" }
      version: { description: "bundle version (must exceed the channel's current one)", required: true }
      label: { description: "version name", required: true }
      confirm: { description: "type PUBLISH-STABLE to publish to stable", required: false, default: "" }
